import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AdminService } from '../../core/admin.service';

type FType = 'text' | 'number' | 'datetime-local' | 'date' | 'select' | 'checkbox' | 'textarea' | 'image' | 'password' | 'email';
interface FieldDef { key: string; label: string; type?: FType; options?: string[]; createOnly?: boolean; }
interface ResourceDef {
  key: string; title: string; single: string; icon: string;
  columns: string[]; fields: FieldDef[];
  inline?: { col: string; options: string[] };   // change a status straight from the table
  noCreate?: boolean; noEdit?: boolean; noDelete?: boolean;
}
interface Group { label: string; items: ResourceDef[]; }

const LEVELS = ['Initiation', 'Debutant', 'Intermediaire', 'Avancee', 'Expert'];

const R: Record<string, ResourceDef> = {
  users: { key: 'users', title: 'Users', single: 'User', icon: '👤',
    columns: ['id', 'name', 'email', 'phone', 'gender', 'age', 'level', 'status', 'preferred_category', 'created_at'],
    inline: { col: 'status', options: ['pending_category', 'pending_approval', 'approved', 'rejected'] },
    fields: [
      { key: 'name', label: 'Name' }, { key: 'email', label: 'Email', type: 'email' },
      { key: 'password', label: 'Password (min 8)', type: 'password', createOnly: true },
      { key: 'phone', label: 'Phone (+216…)' },
      { key: 'gender', label: 'Gender', type: 'select', options: ['', 'male', 'female'] },
      { key: 'age', label: 'Age', type: 'number' },
      { key: 'height_cm', label: 'Height (cm)', type: 'number' }, { key: 'weight_kg', label: 'Weight (kg)', type: 'number' },
      { key: 'goals', label: 'Goals (comma-separated)' },
      { key: 'experience', label: 'Experience' }, { key: 'days_per_week', label: 'Days / week', type: 'number' },
      { key: 'role', label: 'Role', type: 'select', options: ['user', 'admin'] },
      { key: 'level', label: 'Level', type: 'select', options: LEVELS },
      { key: 'status', label: 'Status', type: 'select', options: ['pending_category', 'pending_approval', 'approved', 'rejected'] },
      { key: 'preferred_category', label: 'Preferred category', type: 'select', options: [''] },
    ] },
  memberships: { key: 'memberships', title: 'Memberships', single: 'Membership', icon: '🎫', noCreate: true,
    columns: ['id', 'user_name', 'plan_name', 'status', 'classes_used_this_month', 'started_at', 'renews_at'],
    inline: { col: 'status', options: ['pending', 'active', 'expired', 'cancelled'] },
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['pending', 'active', 'expired', 'cancelled'] },
      { key: 'plan_id', label: 'Plan ID', type: 'number' },
      { key: 'classes_used_this_month', label: 'Classes used this month', type: 'number' },
      { key: 'started_at', label: 'Started', type: 'date' }, { key: 'renews_at', label: 'Renews', type: 'date' },
    ] },
  plans: { key: 'plans', title: 'Plans', single: 'Plan', icon: '💳',
    columns: ['id', 'name', 'price', 'classes_per_month', 'duration_months', 'category', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' }, { key: 'price', label: 'Price (TND)', type: 'number' },
      { key: 'classes_per_month', label: 'Classes / month (blank = unlimited)', type: 'number' },
      { key: 'duration_months', label: 'Duration (months)', type: 'number' },
      { key: 'category', label: 'Category', type: 'select', options: [] },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
    ] },
  classes: { key: 'classes', title: 'Classes', single: 'Class', icon: '🗓️',
    columns: ['id', 'name', 'trainer_name', 'category', 'location', 'level', 'starts_at', 'capacity', 'spots_left'],
    fields: [
      { key: 'name', label: 'Name' }, { key: 'trainer_id', label: 'Trainer', type: 'select', options: [] },
      { key: 'category', label: 'Category', type: 'select', options: [''] },
      { key: 'level', label: 'Level', type: 'select', options: ['', ...LEVELS] },
      { key: 'location', label: 'Location' },
      { key: 'starts_at', label: 'Starts', type: 'datetime-local' }, { key: 'ends_at', label: 'Ends', type: 'datetime-local' },
      { key: 'capacity', label: 'Capacity', type: 'number' },
    ] },
  'class-categories': { key: 'class-categories', title: 'Categories', single: 'Category', icon: '🏷️',
    columns: ['id', 'name', 'is_active', 'sort_order'],
    fields: [{ key: 'name', label: 'Name' }, { key: 'is_active', label: 'Active', type: 'checkbox' }, { key: 'sort_order', label: 'Sort order', type: 'number' }] },
  trainers: { key: 'trainers', title: 'Trainers', single: 'Trainer', icon: '🏋️',
    columns: ['id', 'name', 'specialty'],
    fields: [{ key: 'name', label: 'Name' }, { key: 'specialty', label: 'Specialty' }, { key: 'bio', label: 'Bio', type: 'textarea' }] },
  bookings: { key: 'bookings', title: 'Bookings', single: 'Booking', icon: '✅', noCreate: true, noEdit: true,
    columns: ['id', 'user_name', 'class_name', 'starts_at', 'status'],
    inline: { col: 'status', options: ['booked', 'cancelled', 'attended', 'no_show'] }, fields: [] },
  products: { key: 'products', title: 'Products', single: 'Product', icon: '🛍️',
    columns: ['id', 'name', 'category', 'price', 'stock', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'category', label: 'Category', type: 'select', options: ['supplements', 'apparel', 'accessories'] },
      { key: 'description', label: 'Description', type: 'textarea' },
      { key: 'price', label: 'Price (TND)', type: 'number' }, { key: 'stock', label: 'Stock', type: 'number' },
      { key: 'image', label: 'Image', type: 'image' }, { key: 'is_active', label: 'Active', type: 'checkbox' },
    ] },
  orders: { key: 'orders', title: 'Orders', single: 'Order', icon: '📦', noCreate: true, noEdit: true, noDelete: true,
    columns: ['id', 'user_name', 'user_email', 'total', 'status', 'created_at'],
    inline: { col: 'status', options: ['pending', 'paid', 'fulfilled', 'cancelled'] }, fields: [] },
  announcements: { key: 'announcements', title: 'Announcements', single: 'Announcement', icon: '📣',
    columns: ['id', 'title', 'description', 'link', 'created_at'],
    fields: [
      { key: 'title', label: 'Title' }, { key: 'description', label: 'Description', type: 'textarea' },
      { key: 'link', label: 'Link (optional)' }, { key: 'image', label: 'Image', type: 'image' },
    ] },
  posters: { key: 'posters', title: 'Posters', single: 'Poster', icon: '🖼️',
    columns: ['id', 'username', 'location', 'text', 'created_at'],
    fields: [
      { key: 'username', label: 'Username' }, { key: 'location', label: 'Location' },
      { key: 'text', label: 'Text', type: 'textarea' }, { key: 'image', label: 'Image', type: 'image' },
    ] },
  notifications: { key: 'notifications', title: 'Sent messages', single: 'Message', icon: '🔔', noEdit: true,
    columns: ['id', 'user_name', 'message', 'is_read', 'created_at'],
    fields: [{ key: 'user_id', label: 'User ID', type: 'number' }, { key: 'message', label: 'Message', type: 'textarea' }] },
  workouts: { key: 'workouts', title: 'Workouts', single: 'Workout', icon: '🔥',
    columns: ['id', 'user_name', 'type', 'duration_minutes', 'calories_burned', 'performed_at'],
    fields: [
      { key: 'user_id', label: 'User ID', type: 'number' }, { key: 'type', label: 'Type' },
      { key: 'duration_minutes', label: 'Minutes', type: 'number' }, { key: 'calories_burned', label: 'Calories', type: 'number' },
      { key: 'performed_at', label: 'Date', type: 'date' },
    ] },
  'diet-logs': { key: 'diet-logs', title: 'Diet logs', single: 'Diet log', icon: '🥗',
    columns: ['id', 'user_name', 'meal_type', 'description', 'calories', 'logged_at'],
    fields: [
      { key: 'user_id', label: 'User ID', type: 'number' },
      { key: 'meal_type', label: 'Meal', type: 'select', options: ['breakfast', 'lunch', 'dinner', 'snack'] },
      { key: 'description', label: 'Description' }, { key: 'calories', label: 'Calories', type: 'number' },
      { key: 'logged_at', label: 'Date', type: 'date' },
    ] },
};

const GROUPS: Group[] = [
  { label: 'Members', items: [R['users'], R['memberships'], R['plans']] },
  { label: 'Gym', items: [R['classes'], R['class-categories'], R['trainers'], R['bookings']] },
  { label: 'Store', items: [R['products'], R['orders']] },
  { label: 'Content', items: [R['announcements'], R['posters'], R['notifications']] },
  { label: 'Member logs', items: [R['workouts'], R['diet-logs']] },
];

@Component({
  selector: 'app-admin', standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './admin.component.html', styleUrl: './admin.component.css',
})
export class AdminComponent implements OnInit {
  groups = GROUPS;
  view: string = 'dashboard';          // dashboard | approvals | broadcast | <resource key>
  active: ResourceDef = R['users'];
  rows: any[] = [];
  search = '';
  loading = false; error = ''; info = '';
  navOpen = false;

  stats: any = null;
  pending = 0;
  approvals: any[] = [];

  showForm = false; editingId: number | null = null; formModel: any = {};
  itemsFor: any = null; orderItems: any[] = [];

  bMsg = ''; bAudience: 'all' | 'selected' = 'all'; bUsers: any[] = []; bSel = new Set<number>(); bSearch = ''; bBusy = false;

  constructor(private admin: AdminService, private router: Router) {}

  async ngOnInit() { await this.go('dashboard'); }

  async go(v: string) {
    this.view = v; this.navOpen = false; this.error = ''; this.info = ''; this.search = ''; this.showForm = false;
    try {
      if (v === 'dashboard') { this.stats = await this.admin.stats(); this.pending = this.stats.pending_approvals; }
      else if (v === 'approvals') { this.loading = true; this.approvals = await this.admin.pendingApprovals(); this.pending = this.approvals.length; }
      else if (v === 'broadcast') { this.bUsers = (await this.admin.list('users')).filter((u: any) => u.role !== 'admin'); }
      else {
        this.active = R[v]; this.loading = true; this.rows = [];
        await this.fillOptions();
        this.rows = await this.admin.list(v);
      }
    } catch (e: any) {
      if (e?.status === 401) return this.expired();
      this.error = e?.error?.error || 'Failed to load';
    } finally { this.loading = false; }
  }

  private expired() { this.router.navigate(['/']); }
  async logout() { await this.admin.logout(); this.router.navigate(['/']); }

  // dropdowns that depend on other tables
  private async fillOptions() {
    try {
      const cats = (await this.admin.list('class-categories')).filter(c => c.is_active).map(c => c.name);
      const set = (r: string, k: string, o: string[]) => { const f = R[r].fields.find(f => f.key === k); if (f) f.options = o; };
      set('users', 'preferred_category', ['', ...cats]); set('classes', 'category', ['', ...cats]); set('plans', 'category', cats);
      if (this.active.key === 'classes') { this.trainerList = await this.admin.list('trainers'); }
    } catch {}
  }
  trainerList: any[] = [];

  get filtered() {
    const q = this.search.trim().toLowerCase();
    const list = !q ? this.rows : this.rows.filter(r => this.active.columns.some(c => String(r[c] ?? '').toLowerCase().includes(q)));
    return list.slice(0, 300);
  }

  fmt(v: any, col: string): string {
    if (v === null || v === undefined || v === '') return '—';
    if (col.startsWith('is_')) return v ? 'Yes' : 'No';
    if (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(v)) {
      const d = new Date(v);
      return col.endsWith('_at') && col !== 'date_of_birth' ? d.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : v.slice(0, 10);
    }
    if (col === 'date_of_birth' || col === 'performed_at' || col === 'logged_at') return String(v).slice(0, 10);
    return String(v);
  }
  badge(col: string, v: any) { return ['status'].includes(col) ? String(v).replace(/_/g, '-') : ''; }

  // ---------- CRUD ----------
  openCreate() {
    this.editingId = null; this.error = '';
    this.formModel = this.active.key === 'users' ? { role: 'user', status: 'approved', level: 'Initiation' }
      : this.active.key === 'plans' || this.active.key === 'products' || this.active.key === 'class-categories' ? { is_active: true } : {};
    this.showForm = true;
  }
  openEdit(row: any) {
    this.editingId = row.id; this.error = '';
    this.formModel = { ...row };
    for (const f of this.active.fields) {
      const v = this.formModel[f.key];
      if (typeof v === 'string' && v) {
        if (f.type === 'date') this.formModel[f.key] = v.slice(0, 10);
        else if (f.type === 'datetime-local') this.formModel[f.key] = this.localDt(v);
      }
      if (f.type === 'checkbox') this.formModel[f.key] = !!v;
    }
    this.showForm = true;
  }
  private localDt(v: string) { const d = new Date(v); if (isNaN(+d)) return v.replace(' ', 'T').slice(0, 16); const p = (n: number) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`; }
  cancelForm() { this.showForm = false; this.editingId = null; }
  onFile(e: Event, key: string) { const f = (e.target as HTMLInputElement).files?.[0]; if (f) this.formModel[key] = f; }
  visibleFields() { return this.active.fields.filter(f => !f.createOnly || !this.editingId); }
  trainerOpts() { return this.trainerList; }

  async save() {
    this.error = '';
    try {
      const body = { ...this.formModel };
      if (this.editingId) await this.admin.update(this.active.key, this.editingId, body);
      else await this.admin.create(this.active.key, body);
      this.showForm = false; this.info = 'Saved';
      await this.go(this.active.key);
    } catch (e: any) { if (e?.status === 401) return this.expired(); this.error = e?.error?.error || 'Save failed'; }
  }
  async remove(row: any) {
    if (!confirm(`Delete this ${this.active.single.toLowerCase()}? This cannot be undone.`)) return;
    try { await this.admin.remove(this.active.key, row.id); await this.go(this.active.key); }
    catch (e: any) { this.error = e?.error?.error || 'Delete failed'; }
  }
  async inline(row: any, value: string) {
    const col = this.active.inline!.col; const old = row[col]; row[col] = value;
    try { await this.admin.update(this.active.key, row.id, { [col]: value }); this.info = 'Updated'; }
    catch (e: any) { row[col] = old; this.error = e?.error?.error || 'Update failed'; }
  }
  async resetPw(row: any) {
    const pw = prompt(`New password for ${row.name} (min 8 characters):`);
    if (!pw) return;
    try { await this.admin.resetPassword(row.id, pw); this.info = 'Password reset — user sessions revoked'; }
    catch (e: any) { this.error = e?.error?.error || 'Reset failed'; }
  }
  async showItems(row: any) {
    this.itemsFor = row; this.orderItems = [];
    try { this.orderItems = await this.admin.orderItems(row.id); } catch { this.error = 'Could not load items'; }
  }

  exportCsv() {
    const cols = this.active.columns;
    const esc = (v: any) => `"${String(v ?? '').replace(/"/g, '""')}"`;
    const csv = [cols.join(','), ...this.filtered.map(r => cols.map(c => esc(r[c])).join(','))].join('\n');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv' }));
    a.download = `${this.active.key}.csv`; a.click(); URL.revokeObjectURL(a.href);
  }

  // ---------- approvals ----------
  async approve(row: any) { try { await this.admin.approveUser(row.id); await this.go('approvals'); } catch (e: any) { this.error = e?.error?.error || 'Failed'; } }
  async reject(row: any) { if (!confirm(`Reject ${row.name}?`)) return; try { await this.admin.rejectUser(row.id); await this.go('approvals'); } catch (e: any) { this.error = e?.error?.error || 'Failed'; } }

  // ---------- broadcast ----------
  get bList() { const q = this.bSearch.toLowerCase(); return this.bUsers.filter(u => !q || (u.name + u.email).toLowerCase().includes(q)); }
  bToggle(id: number) { this.bSel.has(id) ? this.bSel.delete(id) : this.bSel.add(id); }
  async send() {
    this.error = ''; this.info = '';
    const msg = this.bMsg.trim();
    if (!msg) { this.error = 'Message is required'; return; }
    if (this.bAudience === 'selected' && !this.bSel.size) { this.error = 'Select at least one user'; return; }
    this.bBusy = true;
    try {
      const r = await this.admin.broadcast(msg, this.bAudience === 'selected' ? [...this.bSel] : undefined);
      this.info = `Sent to ${r.sent} user(s)`; this.bMsg = ''; this.bSel.clear();
    } catch (e: any) { this.error = e?.error?.error || 'Sending failed'; } finally { this.bBusy = false; }
  }

  // ---------- dashboard helpers ----------
  genderPct(g: string) { const t = (this.stats?.gender || []).reduce((a: number, x: any) => a + x.n, 0) || 1; const n = (this.stats?.gender || []).find((x: any) => x.gender === g)?.n || 0; return Math.round(n / t * 100); }
  genderN(g: string) { return (this.stats?.gender || []).find((x: any) => x.gender === g)?.n || 0; }
  get maxSignup() { return Math.max(1, ...(this.stats?.signups || []).map((s: any) => s.n)); }
  money(v: any) { return `${Number(v || 0).toFixed(0)} TND`; }
}
<div class="adm-shell">
  <button class="adm-burger" (click)="navOpen = !navOpen" aria-label="Menu">☰</button>

  <aside class="adm-nav" [class.open]="navOpen">
    <div class="adm-brand">EOS <span>Admin</span></div>
    <button class="adm-nav-btn" [class.on]="view === 'dashboard'" (click)="go('dashboard')">📊 Overview</button>
    <button class="adm-nav-btn" [class.on]="view === 'approvals'" (click)="go('approvals')">
      ⏳ Approvals <b class="adm-pill" *ngIf="pending">{{ pending }}</b>
    </button>
    <button class="adm-nav-btn" [class.on]="view === 'broadcast'" (click)="go('broadcast')">✉️ Send message</button>
    <ng-container *ngFor="let g of groups">
      <div class="adm-group">{{ g.label }}</div>
      <button *ngFor="let r of g.items" class="adm-nav-btn" [class.on]="view === r.key" (click)="go(r.key)">{{ r.icon }} {{ r.title }}</button>
    </ng-container>
    <div class="adm-foot">
      <a routerLink="/app">← Back to app</a>
      <button (click)="logout()">Log out</button>
    </div>
  </aside>

  <main class="adm-main">
    <p class="adm-error" *ngIf="error">{{ error }}</p>
    <p class="adm-info" *ngIf="info">{{ info }}</p>

    <!-- DASHBOARD -->
    <ng-container *ngIf="view === 'dashboard' && stats">
      <h1>Overview</h1>
      <div class="adm-alerts">
        <a (click)="go('approvals')" *ngIf="stats.pending_approvals">⏳ {{ stats.pending_approvals }} account(s) waiting for approval</a>
        <a (click)="go('orders')" *ngIf="stats.pending_orders">📦 {{ stats.pending_orders }} pending order(s)</a>
        <a (click)="go('memberships')" *ngIf="stats.expiring_7d">🎫 {{ stats.expiring_7d }} membership(s) expire within 7 days</a>
        <a (click)="go('products')" *ngIf="stats.low_stock">🛍️ {{ stats.low_stock }} product(s) low on stock</a>
      </div>
      <div class="adm-cards">
        <div class="adm-card" (click)="go('users')"><span>Members</span><b>{{ stats.users }}</b><small>+{{ stats.new_users_7d }} this week</small></div>
        <div class="adm-card" (click)="go('memberships')"><span>Active memberships</span><b>{{ stats.active_memberships }}</b></div>
        <div class="adm-card" (click)="go('classes')"><span>Upcoming classes</span><b>{{ stats.upcoming_classes }}</b><small>{{ stats.bookings_today }} bookings today</small></div>
        <div class="adm-card" (click)="go('trainers')"><span>Trainers</span><b>{{ stats.trainers }}</b></div>
        <div class="adm-card"><span>Membership revenue (month)</span><b>{{ money(stats.membership_revenue_month) }}</b></div>
        <div class="adm-card" (click)="go('orders')"><span>Store revenue (month)</span><b>{{ money(stats.store_revenue_month) }}</b></div>
      </div>
      <div class="adm-two">
        <section class="adm-box">
          <h3>Signups — last 14 days</h3>
          <div class="adm-bars">
            <div *ngFor="let s of stats.signups" class="adm-bar" [title]="s.day + ': ' + s.n">
              <i [style.height.%]="s.n / maxSignup * 100"></i><span>{{ s.n }}</span>
            </div>
            <p *ngIf="!stats.signups.length" class="adm-muted">No signups yet.</p>
          </div>
        </section>
        <section class="adm-box">
          <h3>Gender</h3>
          <div class="adm-gender" *ngFor="let g of ['female', 'male', 'unknown']">
            <label>{{ g }} · {{ genderN(g) }}</label>
            <div class="adm-track"><i [style.width.%]="genderPct(g)"></i></div>
          </div>
        </section>
      </div>
      <section class="adm-box">
        <h3>Latest signups</h3>
        <table class="adm-table">
          <tr *ngFor="let u of stats.recent"><td>{{ u.name }}</td><td>{{ u.email }}</td><td><span class="adm-badge" [attr.data-s]="u.status">{{ u.status }}</span></td><td>{{ u.created_at | date:'medium' }}</td></tr>
        </table>
      </section>
    </ng-container>

    <!-- APPROVALS -->
    <ng-container *ngIf="view === 'approvals'">
      <h1>Pending approvals</h1>
      <p *ngIf="loading">Loading…</p>
      <div class="adm-scroll" *ngIf="!loading && approvals.length">
        <table class="adm-table">
          <thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Category</th><th>Plan</th><th>Price</th><th>Requested</th><th></th></tr></thead>
          <tbody><tr *ngFor="let a of approvals">
            <td>{{ a.name }}</td><td>{{ a.email }}</td><td>{{ a.phone }}</td><td>{{ a.preferred_category }}</td>
            <td>{{ a.plan_name }} ({{ a.duration_months }} mo)</td><td>{{ a.price }} TND</td><td>{{ a.requested_at | date:'short' }}</td>
            <td class="adm-actions"><button class="ok" (click)="approve(a)">Approve</button><button class="bad" (click)="reject(a)">Reject</button></td>
          </tr></tbody>
        </table>
      </div>
      <p *ngIf="!loading && !approvals.length" class="adm-muted">Nothing waiting. 🎉</p>
    </ng-container>

    <!-- BROADCAST -->
    <ng-container *ngIf="view === 'broadcast'">
      <h1>Send a message</h1>
      <section class="adm-box">
        <label class="adm-l">Message
          <textarea [(ngModel)]="bMsg" rows="3" maxlength="500" placeholder="Shown in the member's notifications"></textarea>
        </label>
        <div class="adm-radio">
          <label><input type="radio" name="aud" value="all" [(ngModel)]="bAudience" /> All approved members</label>
          <label><input type="radio" name="aud" value="selected" [(ngModel)]="bAudience" /> Selected ({{ bSel.size }})</label>
        </div>
        <ng-container *ngIf="bAudience === 'selected'">
          <input class="adm-search" placeholder="Search members…" [(ngModel)]="bSearch" />
          <div class="adm-pick"><label *ngFor="let u of bList"><input type="checkbox" [checked]="bSel.has(u.id)" (change)="bToggle(u.id)" /> {{ u.name }} <small>{{ u.email }}</small></label></div>
        </ng-container>
        <button class="adm-primary" [disabled]="bBusy" (click)="send()">{{ bBusy ? 'Sending…' : 'Send' }}</button>
      </section>
    </ng-container>

    <!-- RESOURCE TABLE -->
    <ng-container *ngIf="view !== 'dashboard' && view !== 'approvals' && view !== 'broadcast'">
      <div class="adm-head">
        <h1>{{ active.title }} <small>{{ rows.length }}</small></h1>
        <div class="adm-tools">
          <input class="adm-search" placeholder="Search…" [(ngModel)]="search" />
          <button (click)="exportCsv()" [disabled]="!rows.length">Export CSV</button>
          <button class="adm-primary" *ngIf="!active.noCreate" (click)="openCreate()">+ Add</button>
        </div>
      </div>
      <p *ngIf="loading">Loading…</p>
      <div class="adm-scroll" *ngIf="!loading && filtered.length">
        <table class="adm-table">
          <thead><tr><th *ngFor="let c of active.columns">{{ c.replace('_', ' ') }}</th><th></th></tr></thead>
          <tbody><tr *ngFor="let row of filtered">
            <td *ngFor="let c of active.columns">
              <select *ngIf="active.inline && active.inline.col === c" class="adm-inline" [ngModel]="row[c]" (ngModelChange)="inline(row, $event)">
                <option *ngFor="let o of active.inline.options" [value]="o">{{ o }}</option>
              </select>
              <ng-container *ngIf="!(active.inline && active.inline.col === c)">
                <span *ngIf="c === 'status'" class="adm-badge" [attr.data-s]="row[c]">{{ row[c] }}</span>
                <ng-container *ngIf="c !== 'status'">{{ fmt(row[c], c) }}</ng-container>
              </ng-container>
            </td>
            <td class="adm-actions">
              <button *ngIf="active.key === 'orders'" (click)="showItems(row)">Items</button>
              <button *ngIf="active.key === 'users'" (click)="resetPw(row)">Reset pw</button>
              <button *ngIf="!active.noEdit" (click)="openEdit(row)">Edit</button>
              <button *ngIf="!active.noDelete" class="bad" (click)="remove(row)">Delete</button>
            </td>
          </tr></tbody>
        </table>
      </div>
      <p *ngIf="!loading && !filtered.length" class="adm-muted">No records.</p>
    </ng-container>
  </main>

  <!-- FORM MODAL -->
  <div class="adm-back" *ngIf="showForm" (click)="cancelForm()">
    <div class="adm-modal" (click)="$event.stopPropagation()">
      <h3>{{ editingId ? 'Edit' : 'Add' }} {{ active.single.toLowerCase() }}</h3>
      <p class="adm-error" *ngIf="error">{{ error }}</p>
      <form (ngSubmit)="save()">
        <label *ngFor="let f of visibleFields()" [class.adm-check]="f.type === 'checkbox'">
          {{ f.label }}
          <select *ngIf="f.type === 'select' && f.key !== 'trainer_id'" [(ngModel)]="formModel[f.key]" [name]="f.key">
            <option *ngFor="let o of f.options" [value]="o">{{ o || '—' }}</option>
          </select>
          <select *ngIf="f.key === 'trainer_id'" [(ngModel)]="formModel[f.key]" [name]="f.key" required>
            <option *ngFor="let t of trainerOpts()" [ngValue]="t.id">{{ t.name }}</option>
          </select>
          <input *ngIf="f.type === 'checkbox'" type="checkbox" [(ngModel)]="formModel[f.key]" [name]="f.key" />
          <textarea *ngIf="f.type === 'textarea'" [(ngModel)]="formModel[f.key]" [name]="f.key" rows="3"></textarea>
          <ng-container *ngIf="f.type === 'image'">
            <img *ngIf="formModel['image_url']" [src]="formModel['image_url']" class="adm-preview" alt="" />
            <input type="file" accept="image/png,image/jpeg,image/webp" [name]="f.key" (change)="onFile($event, f.key)" />
          </ng-container>
          <input *ngIf="!f.type || ['text','number','date','datetime-local','password','email'].includes(f.type)"
                 [type]="f.type || 'text'" [(ngModel)]="formModel[f.key]" [name]="f.key" [step]="f.type === 'number' ? 'any' : null" />
        </label>
        <div class="adm-modal-actions">
          <button type="button" (click)="cancelForm()">Cancel</button>
          <button type="submit" class="adm-primary">Save</button>
        </div>
      </form>
    </div>
  </div>

  <!-- ORDER ITEMS MODAL -->
  <div class="adm-back" *ngIf="itemsFor" (click)="itemsFor = null">
    <div class="adm-modal" (click)="$event.stopPropagation()">
      <h3>Order #{{ itemsFor.id }} — {{ itemsFor.user_name }}</h3>
      <table class="adm-table"><tr *ngFor="let i of orderItems"><td>{{ i.product_name }}</td><td>×{{ i.quantity }}</td><td>{{ i.unit_price }} TND</td></tr></table>
      <p><b>Total: {{ itemsFor.total }} TND</b></p>
      <div class="adm-modal-actions"><button (click)="itemsFor = null">Close</button></div>
    </div>
  </div>
</div>
